<?php
require __DIR__ . '/app/services.php';$u=require_role('Admin','Officer');$sid=(int)($_GET['id']??0);$st=one('SELECT s.*,u.is_active FROM students s JOIN users u ON u.id=s.user_id WHERE s.id=?',[$sid]);if(!$st) fail('Student not found',404);
$history=attendance_for_student($sid);$fines=get_fines($sid);
page_header('Student Profile',$u);title_block('Student Profile','Attendance, QR identity, fines and payment history.','<a class="btn btn-ghost" href="'.h(app_path('students.php')).'">← Student Directory</a>');
?><section class="id-card" style="margin-bottom:20px"><div class="id-avatar"><?=h(substr($st['first_name'],0,1))?></div><div><h2><?=h($st['last_name'].', '.$st['first_name'].' '.$st['middle_name'])?></h2><p>Student #<?=h($st['student_number'])?></p><div class="id-meta"><span><?=h($st['program'])?></span><span>Year <?=h($st['year_level'])?></span><span>Section <?=h($st['section'])?></span></div></div><a class="btn btn-primary" style="margin-left:auto" href="<?=h(app_path('qr.php?id='.$sid))?>">View QR</a><?php if($u['role']==='Admin'):?><form method="post" action="<?=h(app_path('students.php'))?>"><?=csrf_field()?><input type="hidden" name="action" value="rotate_qr"><input type="hidden" name="id" value="<?=h($sid)?>"><button class="btn btn-ghost" data-confirm="Regenerate student QR? Old printed QR codes will stop working.">Regenerate QR</button></form><?php endif;?></section>
<div class="cards"><div class="card"><div class="kicker">Registered Events</div><div class="metric"><?=count($history)?></div></div><div class="card"><div class="kicker">Present / Late</div><div class="metric"><?=count(array_filter($history,fn($a)=>in_array($a['attendance_status'],['present','late'],true)))?></div></div><div class="card"><div class="kicker">Unpaid Balance</div><div class="metric accent"><?=pesos(outstanding($sid))?></div></div><div class="card"><div class="kicker">Account</div><p style="margin-top:14px"><?=status_badge($st['is_active']?'active':'inactive')?></p></div></div>
<section class="panel"><h2>Attendance History</h2><div class="table-scroll"><table class="table"><thead><tr><th>Event</th><th>Date</th><th>Time In</th><th>Time Out</th><th>Status</th></tr></thead><tbody><?php foreach($history as $a):?><tr><td><?=h($a['title'])?></td><td><?=h(substr($a['starts_at'],0,10))?></td><td><?=h($a['time_in']??'—')?></td><td><?=h($a['time_out']??'—')?></td><td><?=status_badge($a['attendance_status'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$history):?><p class="empty">No attendance yet.</p><?php endif;?></section>
<section class="panel"><div class="row between"><h2>Fines and Verified Payments</h2><a class="btn btn-primary btn-sm" href="<?=h(app_path('fines.php?student_id='.$sid))?>">Record Payment / View History</a></div><div class="table-scroll"><table class="table"><thead><tr><th>Event</th><th>Reason</th><th>Fine</th><th>Verified Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody><?php foreach($fines as $f):?><tr><td><?=h($f['title'])?></td><td><?=h($f['reason'])?></td><td><?=pesos($f['amount'])?></td><td><?=pesos($f['paid'])?></td><td><?=pesos($f['status']==='waived'?0:max(0,(float)$f['amount']-(float)$f['paid']))?></td><td><?=status_badge($f['status'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$fines):?><p class="empty">No fines recorded.</p><?php endif;?></section><?php page_footer();
